  Lemma masks_facts :
    0 <= iav < 2 ^ cnt /\ 0 <= ifr < 2 ^ cnt /\ Z.land iav ifr = 0 /\ Z.lor iav ifr = itot /\
    iav < 2 ^ (aidx + 1) /\
    (forall j, 0 <= j -> Z.testbit ifr j = ((1 <=? j) && (j <? cnt) && (aidx + 1 <=? j))%bool) /\
    (forall j, 0 <= j -> Z.testbit (Z.lor iav ifr) j = ((1 <=? j) && (j <? cnt))%bool).
